def model(p,eps,T):
    a,b,c,d,e,f,g,h,i,j,pw,q=p
    num = a + b*T**(-pw) + (c + d*T**(-pw) + f*T**q)*eps + g*eps**2
    den = 1 + e*eps + h*eps**2 + (j*T**(-pw))*eps*eps
    return -eps*num/den*np.exp(-(i)*eps)
